# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HADİS TARİHİNİN DÖRT TEMEL DÖNEMİ VE ÖZET SENTEZİ (HDS.10.2.3)</text>\n  <rect x="20" y="42" width="155" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="97" y="64" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. TESBİT DÖNEMİ</text>\n  <text x="28" y="88" font-size="10.2" fill="#1e3a8a">• Asr-ı Saâdet ve Sahâbe</text>\n  <text x="28" y="110" font-size="10.2" fill="#1e3a8a">• Ezber (hıfz) ve ilk özel</text>\n  <text x="28" y="126" font-size="10.2" fill="#1e3a8a">  sahîfeler (es-Sahîfetü\'s-</text>\n  <text x="28" y="142" font-size="10.2" fill="#1e3a8a">  Sâdıka, Sahîfe-i Hemmâm)</text>\n  <text x="28" y="164" font-size="10.2" fill="#1e3a8a">• İsnad ve rihle başlangıcı</text>\n  <rect x="188" y="42" width="155" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="265" y="64" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. TEDVİN DÖNEMİ</text>\n  <text x="196" y="88" font-size="10.2" fill="#14532d">• Hicri I. asır sonu - II. asır</text>\n  <text x="196" y="110" font-size="10.2" fill="#14532d">• Halife Ömer b. Abdülazîz</text>\n  <text x="196" y="132" font-size="10.2" fill="#14532d">• İbn Şihâb ez-Zührî</text>\n  <text x="196" y="154" font-size="10.2" fill="#14532d">• Dağınık sahîfelerin resmî</text>\n  <text x="196" y="170" font-size="10.2" fill="#14532d">  olarak bir araya toplanması</text>\n  <rect x="356" y="42" width="155" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="433" y="64" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">3. TASNİF DÖNEMİ</text>\n  <text x="364" y="88" font-size="10.2" fill="#581c87">• Hicri II. ortası - III. asır</text>\n  <text x="364" y="110" font-size="10.2" fill="#581c87">• Ale\'l-ebvâb (Musannef,</text>\n  <text x="364" y="126" font-size="10.2" fill="#581c87">  Muvatta, Câmi\', Sünen)</text>\n  <text x="364" y="148" font-size="10.2" fill="#581c87">• Ale\'r-ricâl (Müsned, Mu\'cem)</text>\n  <text x="364" y="170" font-size="10.2" fill="#581c87">• Kütüb-i Sitte ve Kütüb-i Tis\'a</text>\n  <rect x="524" y="42" width="156" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="602" y="64" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">4. TASNİF SONRASI</text>\n  <text x="532" y="88" font-size="10.2" fill="#7c2d12">• Hicri IV. asır ve sonrası</text>\n  <text x="532" y="110" font-size="10.2" fill="#7c2d12">• Müstedrek ve Müstahrec</text>\n  <text x="532" y="132" font-size="10.2" fill="#7c2d12">• Cem\' ve Zevâid eserleri</text>\n  <text x="532" y="154" font-size="10.2" fill="#7c2d12">• Şerh, Etrâf ve Kırk Hadis</text>\n  <text x="532" y="176" font-size="10.2" fill="#7c2d12">• Usul eserlerinin telifi</text>\n  <rect x="20" y="224" width="660" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hadis tarihi; ezber ve yazıyla koruma (tesbit), toplama (tedvin), sınıflandırma (tasnif) ve şerh-değerlendirme zinciridir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">3. ÜNİTEYE GİRİŞ: HADİSİN YAPISI (SENED VE METİN UNSURLARI)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. SENED / İSNAD (RÂVİLER ZİNCİRİ)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Hadisi nakleden râvilerin isim zinciridir</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• Hadisin Hz. Peygamber\'e aidiyet belgesidir</text>\n  <text x="35" y="136" font-size="11.2" fill="#1e3a8a">• Musannif → Hocası → Tebeü\'t-tâbiîn → Tâbiîn → Sahâbî</text>\n  <text x="35" y="160" font-size="11.2" fill="#1e3a8a">• Örnek: «Bize Humeydî anlattı, ona Süfyân, ona Yahyâ,</text>\n  <text x="35" y="180" font-size="11.2" fill="#1e3a8a">  ona Alkame, ona da Hz. Ömer b. Hattâb (r.a.) bildirdi...»</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">2. METİN (HADİSİN SÖZ VE MESAJ KISMI)</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• Senedin bittiği yerden başlayan asıl Peygamber sözüdür</text>\n  <text x="370" y="112" font-size="11.2" fill="#064e3b">• Kavlî (söz), fiilî (davranış) veya takrîrî (onay) içeriktir</text>\n  <text x="370" y="136" font-size="11.2" fill="#064e3b">• Dinî, ahlaki ve hukuki hükmün yer aldığı bölümdür</text>\n  <text x="370" y="160" font-size="11.2" fill="#064e3b">• Örnek: «...Ameller niyetlere göredir. Herkese ancak</text>\n  <text x="370" y="180" font-size="11.2" fill="#064e3b">  niyet ettiği şey vardır...» (Buhârî, Bed\'ü\'l-vahy, 1)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bir hadis hem senedinin kopuksuz ve güvenilir olması hem de metninin Kur\'an ve sünnete uygunluğuyla incelenir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">HADİS USULÜNÜN TEMEL KAVRAMLARI (HDS.10.3.1)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">RÂVİ VE NİTELİKLERİ (ADÂLET VE ZABT)</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Râvi: Hadisi senediyle alıp başkasına nakleden kimse</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• Adâlet: Râvinin dindar, takvalı ve dürüst olması</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">• Zabt: Râvinin ezber ve yazı korumasının sağlamlığı</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• Sika: Hem adâlet hem zabt sahibi güvenilir râvi</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• Cerh ve Ta\'dîl: Râvileri güvenilirlik açısından inceleme</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">USUL, RİVAYET VE TAHAMMÜL KAVRAMLARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#713f12">• Hadis Usulü: Hadislerin sıhhatini inceleyen yöntem ilmi</text>\n  <text x="370" y="112" font-size="11.2" fill="#713f12">• Tahammülü\'l-ilm: Hadisi hocadan usulüne göre alma</text>\n  <text x="370" y="136" font-size="11.2" fill="#713f12">• Edâ / Rivayet: Alınan hadisi öğrencilere nakletme</text>\n  <text x="370" y="160" font-size="11.2" fill="#713f12">• Tarîk / Vecih: Hadisin geliş yollarından her biri</text>\n  <text x="370" y="184" font-size="11.2" fill="#713f12">• Muhaddis: Hadis ilmiyle ve rivayetiyle uzmanlaşan âlim</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Abdullah b. Mübârek: «İsnad dinin bir parçasıdır; eğer isnad olmasaydı dileyen dilediğini söylerdi.»</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
